+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final String INVALID_EMAIL = "Enter a valid e-mail address";
+    private static final EmailValidator EMAIL_VALIDATOR =
+            new EmailValidator(INVALID_EMAIL);
+
+    private final MessageService messageService;
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send", event -> send());
+    private final Grid<ContactMessage> messages = new Grid<>();
+
+    private boolean clearingAfterSend;
+    private Dialog leaveDialog;
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        // Keep server-side state current on every edit. Besides immediate button
+        // re-enabling, this ensures a navigation click cannot outrun a pending value.
+        name.setValueChangeMode(ValueChangeMode.EAGER);
+        email.setValueChangeMode(ValueChangeMode.EAGER);
+        phone.setValueChangeMode(ValueChangeMode.EAGER);
+        message.setValueChangeMode(ValueChangeMode.EAGER);
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        FormLayout form = new FormLayout();
+        form.add(name, email, phone, message);
+        form.setResponsiveSteps(new FormLayout.ResponsiveStep("0", 1),
+                new FormLayout.ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+        add(form, send);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name");
+        messages.addColumn(ContactMessage::message).setHeader("Message");
+        messages.setItems(messageService.findAllNewestFirst());
+        add(messages);
+
+        name.addValueChangeListener(event -> edited());
+        email.addValueChangeListener(event -> edited());
+        phone.addValueChangeListener(event -> edited());
+        message.addValueChangeListener(event -> edited());
+
+        // This also makes Enter work while focus is in any of the form fields.
+        send.addClickShortcut(Key.ENTER);
+    }
+
+    private void edited() {
+        if (!clearingAfterSend) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void send() {
+        if (!validate()) {
+            return;
+        }
+
+        messageService.save(new ContactMessage(
+                name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        messages.setItems(messageService.findAllNewestFirst());
+
+        clearingAfterSend = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+        } finally {
+            clearingAfterSend = false;
+        }
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean validate() {
+        clearValidation();
+        boolean valid = true;
+
+        if (name.getValue().isBlank()) {
+            name.setInvalid(true);
+            name.setErrorMessage("Name is required");
+            valid = false;
+        }
+
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        if (!emailValue.isEmpty()
+                && EMAIL_VALIDATOR.apply(emailValue, null).isError()) {
+            email.setInvalid(true);
+            email.setErrorMessage(INVALID_EMAIL);
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            email.setInvalid(true);
+            email.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (message.getValue().isBlank()) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            message.setInvalid(true);
+            message.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        }
+
+        return valid;
+    }
+
+    private void clearValidation() {
+        name.setInvalid(false);
+        name.setErrorMessage(null);
+        email.setInvalid(false);
+        email.setErrorMessage(null);
+        phone.setInvalid(false);
+        phone.setErrorMessage(null);
+        message.setInvalid(false);
+        message.setErrorMessage(null);
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsavedInput()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        if (leaveDialog != null && leaveDialog.isOpened()) {
+            navigation.cancel();
+            return;
+        }
+
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        Button keepEditing = new Button("Keep editing", click -> {
+            navigation.cancel();
+            dialog.close();
+        });
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(new HorizontalLayout(keepEditing, discard));
+        dialog.addOpenedChangeListener(opened -> {
+            if (!opened.isOpened()) {
+                leaveDialog = null;
+            }
+        });
+        leaveDialog = dialog;
+        dialog.open();
+    }
+
+    private boolean hasUnsavedInput() {
+        return !name.isEmpty() || !email.isEmpty() || !phone.isEmpty() || !message.isEmpty();
+    }
+}
