+package com.example.contact;
+
+import org.springframework.stereotype.Service;
+
+import java.util.ArrayList;
+import java.util.List;
+
+/**
+ * Application-wide, in-memory storage for submitted messages.
+ *
+ * <p>The service deliberately has no persistence: its singleton lifetime is enough to
+ * keep messages available while users navigate between views.</p>
+ */
+@Service
+public class MessageService {
+
+    private final List<ContactMessage> messages = new ArrayList<>();
+
+    public synchronized void save(ContactMessage message) {
+        messages.addFirst(message);
+    }
+
+    public synchronized List<ContactMessage> findAllNewestFirst() {
+        return List.copyOf(messages);
+    }
+}
